"""Conditional probability, total probability, Bayes and independent trials."""
import math
import manual_solutions as author
from matrix_workings import sp,L

def put(group,n,steps,errors,solution=None):
 author.add('PS3',f'{group:03}-{n:03}',steps,errors,'逐问明确条件事件、抽样模型、分支权重、计算过程及边界；独立核对概率归一化。')
 if solution is not None:author.PATCHES[f'SRC-PS3-E{group:03}-{n:03}']['solution']=solution
def example(n,steps,errors):
 author.add_example('PS3',n,steps,errors,'按样本空间与条件逐步推导，核对全概率、后验或试验次数阈值。')
R=sp.Rational

def bayes(priors,likelihoods,names,event,posterior=()):
 assert sum(priors)==1 and len(priors)==len(likelihoods)==len(names)
 assert all(0<=x<=1 for x in priors+likelihoods)
 weights=[p*l for p,l in zip(priors,likelihoods)];total=sum(weights);assert total>0
 out=[f'将样本空间按{len(names)}个互斥且穷尽的来源Hᵢ划分，观察事件E为“{event}”。先验P(Hᵢ)与条件概率P(E|Hᵢ)作用不同，先相乘得联合概率，再跨来源求和。']
 for i,(p,l,w,name) in enumerate(zip(priors,likelihoods,weights,names),1):
  out+=['来源H'+str(i)+'为“'+name+'”：$$P(H_{'+str(i)+'})='+L(p)+r',\quad P(E\mid H_{'+str(i)+'})='+L(l)+r',\quad P(H_{'+str(i)+r'}\cap E)=('+L(p)+')('+L(l)+')='+L(w)+'.$$']
 out+=['由全概率公式 $$P(E)='+ '+'.join(L(w) for w in weights)+'='+L(total)+r'\approx '+format(float(total),'.8g')+'.$$分支互斥，所以这些联合概率可直接相加。']
 for i in posterior:
  result=sp.cancel(weights[i]/total)
  out+=['已知E后，来源“'+names[i]+'”的后验由贝叶斯公式归一化：$$P(H_{'+str(i+1)+r'}\mid E)=\frac{P(H_{'+str(i+1)+r'}\cap E)}{P(E)}=\frac{'+L(weights[i])+'}{'+L(total)+'}='+L(result)+r'\approx '+format(float(result),'.8g')+'.$$']
 if len(posterior)==len(priors):out+=['全部后验概率之和为1，因为使用的是同一个总概率分母，检查来源没有漏项或重复。']
 return out

put(8,1,[r'条件概率定义P(B|A)=P(AB)/P(A)，P(A)=0.5>0，故可移项P(AB)=P(A)P(B|A)=0.5×0.8=0.4。这里0.8是给定的条件概率，不是P(B)。',r'用加法公式P(A∪B)=0.5+0.6−0.4=0.7。“A、B都不发生”为并集的补，因此P(补A交补B)=1−0.7=0.3。',r'四块核查：仅A=0.1，仅B=0.2，两者同发生0.4，两者均不0.3，加起来1。P(A)P(B)=0.3不等于交概率0.4，不能把A、B看成独立。'],[r'B|A与B的边际概率不同，分母必须是已知条件A的概率。',r'都不发生是否定并集，不是否定交集。'])
put(8,2,[r'设F为投入基金、S为购买股票，题给P(F)=0.58、P(S)=0.28、P(FS)=0.19。两问条件方向相反，分子相同而分母不同。',r'第（1）已知F，条件样本范围缩至F，P(S|F)=0.19/0.58=19/58≈0.327586。第（2）已知S，P(F|S)=0.19/0.28=19/28≈0.678571。',r'两概率均在0与1之间，且分别乘回各自条件事件概率都得到同一个0.19，核对分母方向。它们不是投资收益率，只是题设人群中的条件事件比例。'],[r'“已知谁”决定分母，条件概率一般不对称。',r'不能把两种投资都做的19%直接当条件比例。'])
put(8,3,[r'设T为电信学院、G为女生。全校男女3∶2给P(G)=2/(3+2)=0.4；P(T)=0.1，电信中女生占5%给P(G|T)=0.05，不是P(TG)=0.05。',r'先算联合P(TG)=P(T)P(G|T)=0.1×0.05=0.005。已知抽到女生，求反方向P(T|G)=P(TG)/P(G)=0.005/0.4=0.0125。',r'可用10000人作比例核查：全校女生4000，电信1000，其中女生50；女生内电信占50/4000=1.25%。比例基准不同是两层百分数相乘再除全校女生率的原因。'],[r'“其中女生5%”分母是电信学院，不能直接当全校女生比例。',r'目标是电信|女生，不能误求女生|电信。'])
put(8,4,[r'采用两个孩子性别独立、男女各1/2的模型，按老大、老二排序，BB、BG、GB、GG四种各概率1/4。B表示男、G表示女。',r'第（1）已知老大为G，保留GB、GG两种等可能结果；其中老二男仅GB，故概率1/2。',r'第（2）按原例将“有一个女孩”理解为至少一个G，保留BG、GB、GG三种，混合性别占其中BG、GB两种，故“另一个男孩”的概率2/3。',r'两问收到的信息不同：第（1）指定了位置，第（2）只排除BB。如果问题是随机遇见一个指定孩子并确认她是女孩，观察机制会不同，不能自动套第（2）的三结果条件空间。'],[r'至少一个女孩仍包含GG，不能把它删去。',r'条件是否指定老大决定条件空间，1/2与2/3不是矛盾。'])
put(8,5,[r'100件中次品10、正品90。“第三次才取得正品”意味着前两次次品且第三次正品，并不是第三次正品而前面任意。',r'依条件乘法，第一次次品10/100；已取走一次品后第二次次品9/99；再取走一次品后余98件中正品仍90，第三次正品90/98。',r'相乘P=(10/100)(9/99)(90/98)=9/1078≈0.008349。每一次分母与剩余库存对应，且正品数在前两次抽次品后没有减少。'],[r'“第三次才”规定前两次失败，不能只写90/100。',r'不放回会改变分母和次品数，不可用0.1²×0.9。'])
put(8,6,[r'将每个通过率理解为已经获准参加该科时的条件通过概率。按闯关乘法，拿证需要四科依次通过：P(证)=0.95×0.6×0.5×0.9=0.2565。条件链本身已足够，不需额外假定未参加科目的结果独立。',r'题意中的“科二未通过”按已进入科二但在该科失败处理，概率P(F₂)=0.95×(1−0.6)=0.38；要先通过科一，所以不能单用0.4。F₂必属于未拿证事件。',r'未拿证概率1−0.2565=0.7435，故P(F₂|未拿证)=0.38/0.7435=760/1487≈0.511096。',r'分支总和核查：科一失败0.05，科二失败0.38，科三失败0.285，科四失败0.0285，拿证0.2565，和1。若把尚未参加科二也叫“科二未通过”，那是另一事件，不同于本解所用失败分支。'],[r'到某科失败必须同时计算此前各科都过的概率。',r'未拿证是条件事件，分母包括全部失败路径，不只包括科二。'])
put(8,7,[r'先把交的补分割求出：P(A补B)=P(A)−P(AB)=0.35，P(补AB)=P(B)−P(AB)=0.15；P(补B)=0.7、P(补A)=0.5，四个条件分母均正。',r'因此P(A|B)=0.15/0.3=0.5=P(A)；P(A|补B)=0.35/0.7=0.5=P(A)。',r'另两项P(B|A)=0.15/0.5=0.3=P(B)；P(B|补A)=0.15/0.5=0.3=P(B)。',r'给定交概率0.15恰等于0.5×0.3，独立性也能统一解释四个等式。但本题已按定义逐项核对，特别是P(A补B)与P(补AB)不能仅因符号相像而视作同一数。'],[r'补的是哪个事件要分清，A交补B概率0.35，补A交B概率0.15。',r'条件分母若为0不能用这种比值，本题四个均非零。'])

put(9,1,[r'第（1）选择袋的两条路径各1/2，而不是每颗球在合并后等机会被抽。']+bayes([R(1,2),R(1,2)],[R(6,10),R(8,14)],['甲袋','乙袋'],'取红球')+[r'第（2）合袋后共10+14=24球，红球6+8=14，每球等可能，所以概率14/24=7/12≈0.583333。两次试验的选袋权重不同，因此第（1）的41/70与第（2）不必相等。'],[r'等可能选袋不等于按袋内球数加权选袋。',r'合并后分母是24，不是先平均两个红球比例。'])
