put(11,1,[r'已知独立按乘法定义P(AB)=P(A)P(B)，该定义不要求条件概率分母非零，因此证明也可覆盖P(A)或P(B)为0、1的边界。',r'先把A分为AB和A补B两个互斥部分：P(A补B)=P(A)−P(AB)=P(A)[1−P(B)]=P(A)P(补B)，所以A与补B独立。',r'再用德摩根和加法公式：P(补A交补B)=1−P(A∪B)=1−P(A)−P(B)+P(A)P(B)=[1−P(A)][1−P(B)]，所以两补事件独立。',r'同理P(补A交B)=P(B)−P(AB)=P(补A)P(B)。互补任一事件仍独立的结论来自这些确切分割，不是来自“看起来互不影响”。'],[r'不要用可能分母为0的条件概率来作全边界证明。',r'独立与互斥不同，一般独立事件的交概率不是0。'])
put(11,2,[r'令D=AB。D包含于A，也包含于A∪B，所以D∩A=D、D∩(A∪B)=D，两个条件概率分子相同，均为P(D)。',r'按定义P(D|A)=P(D)/P(A)，P(D|A∪B)=P(D)/P(A∪B)。A包含于A∪B给P(A∪B)≥P(A)>0，两分母均合法。',r'因分子非负，同一分子除以较小正数所得较大，便有目标不等式；若P(D)=0，两者都为0取等。本证明不要求A、B独立。'],[r'被条件化的是交事件AB，不是单独的B。',r'分母增大时同一非负分子的比值减小，别反向。'])
put(11,3,[r'独立给P(AB)=pq，且任一补事件仍与另一事件独立。第一问加法公式P(A∪B)=p+q−pq。',r'第二问P(A∪补B)=p+(1−q)−p(1−q)=1−q+pq。也可取对立补A交B，概率(1−p)q，结果1−(1−p)q。',r'第三问补A并补B是AB的补，概率1−pq。三式在p=0、1或q=0、1时也成立，确认未作非法除法。'],[r'补A并补B是AB的补；补A交补B才是A并B的补。',r'第二问交项为p(1−q)，不能沿用pq。'])
put(11,4,[r'设p=P(A)、q=P(B)。独立及补事件独立给P(A补B)=p(1−q)、P(补AB)=(1−p)q。题给二者相同，消去共同pq得p=q。',r'又P(补A交补B)=(1−p)(1−q)=1/9，代q=p得(1−p)²=1/9。因0≤p≤1，1−p非负，只能取1/3，故p=q=2/3。',r'反代P(补A补B)=1/3×1/3=1/9，两侧交概率均2/9，全部条件满足。平方方程形式上的另一根4/3超出概率范围，应舍去。'],[r'开平方后要用概率在[0,1]内筛根。',r'两个交事件相等的概率只能先推出p=q，不能直接说A=B。'])
put(11,5,[r'设三个成功事件独立，成功率分别0.25、0.35、0.4。“密码被译出”只需至少一人成功，对立是三人全失败。',r'各失败率0.75、0.65、0.6，补事件也相互独立，全失败概率0.75×0.65×0.6=0.2925。',r'所求1−0.2925=0.7075。直接把三个成功率相加会重复计算多人同时成功的情况，且可能超1；用对立事件避免这些重叠。'],[r'至少一人成功不是三人都成功。',r'联合失败率相乘的依据是独立性。'])
put(11,6,[r'元件正常概率1−p。每支路两个串联，需两个都正常，独立给支路正常率(1−p)²，支路失效为1−(1−p)²。',r'三支路并联，装置只有在三支路全失效时失效。每条支路使用不同的两个元件，六元件相互独立使这三个支路状态也独立，因此全失效率[1−(1−p)²]³。',r'装置正常率1−[1−(1−p)²]³。p=0全部完好时结果1，p=1全坏时结果0；边界吻合。不能把六元件全串联成(1−p)⁶。'],[r'支路内部串联用正常率乘积，支路之间并联用全失效的补。',r'独立支路依赖它们由不同的独立元件组成，不能忽略结构。'])

put(12,1,[r'按5个工作日故障相互独立、各日故障率0.2的题设，故障天数X为二项分布B(5,0.2)。恰3天故障指任意3个日期故障，其余2天正常。',r'指定一组故障日期概率为0.2³0.8²，这样的三日子集有C(5,3)=10个，互斥，所以P(X=3)=10×0.008×0.64=0.0512。',r'组合数用于选择具体故障日期，不能漏掉；若只算某个固定前三天坏、后两天好，那只是0.00512，只有目标事件的十分之一。'],[r'“恰3天”允许日期的10种组合，不是前三天固定坏。',r'题目采用5个工作日，不是自然周7天。'])
put(12,2,[r'把误点记成功事件，概率1−0.8=0.2。采用5架飞机是否准点相互独立、同率的模型，误点架数X∼B(5,0.2)。',r'恰1架误点：先选择是哪一架有C(5,1)=5种；指定该架误点其余四架准点的概率0.2×0.8⁴=0.08192，所以所求0.4096。',r'独立性是二项模型的依据；仅给每架准点边际率0.8不足以排除共同天气导致的相关，若不采用这个模型则不能单由题给边际率确定联合概率。'],[r'只有一架误点意味着四架准点，0.2与0.8的幂不能调换。',r'独立性须作为本题计算模型说明。'])
put(12,3,[r'寿命超过1000小时的概率0.2，是仍完好的概率，不是坏的概率；按通常“用满1000小时后”口径把坏定义为寿命不超过1000小时，则坏概率0.8。取三灯寿命独立。',r'最多1个坏分为0坏（3好）和1坏（2好），两种互斥。P(0坏)=0.2³=0.008；P(1坏)=C(3,1)0.8×0.2²=0.096。',r'相加0.104。也可由完好数Y∼B(3,0.2)，求P(Y≥2)得相同值；这说明“至多一个坏”对应至少两个好，不能误读成至多一个好。'],[r'题给0.2对应存活，故障率应为0.8。',r'最多1坏还包括全好，不能只保留恰1坏。'])
put(12,4,[r'各电梯独立且运行率3/4，运行部数X∼B(4,3/4)，每部不运行率1/4。三问分别对应X≥1、X=2、X=4。',r'第（1）至少一部运行，用全不运行的补：1−(1/4)⁴=255/256。第（2）恰一半即2部，C(4,2)(3/4)²(1/4)²=6×9/256=27/128。',r'第（3）全部运行概率(3/4)⁴=81/256。第二问不能把“这一半”当作固定的两部，须乘6种选择。'],[r'一半4部是2部，且是哪2部未指定。',r'至少一部与恰一部不同，前者最方便用对立事件。'])
put(12,5,[r'设单次发生率p，三次独立且同率。至少一次的对立是三次全不发生，所以1−(1−p)³=19/27。',r'移项得(1−p)³=8/27，因0≤p≤1，可取实数立方根1−p=2/3，故p=1/3。',r'反代1−(2/3)³=1−8/27=19/27，满足原条件。不能把至少一次概率直接除以3，因为一次、两次、三次发生的情形有重叠。'],[r'独立才给全不发生概率的三次方。',r'至少一次不是三个边际概率的简单相加。'])
put(12,6,[r'按独立重复掷均匀骰子的模型，单次未出6概率5/6。n次至少出过一次6概率1−(5/6)ⁿ，要求它≥0.9。',r'等价(5/6)ⁿ≤0.1，取对数得n ln(5/6)≤ln0.1。ln(5/6)<0，除它时不等号翻转，所以n≥ln0.1/ln(5/6)≈'+format(math.log(.1)/math.log(5/6),'.8f')+'。',r'最小整数13。检验12次概率≈'+format(1-(5/6)**12,'.8f')+'<0.9，13次≈'+format(1-(5/6)**13,'.8f')+'≥0.9，且次数增加概率不减，故最小性已证明。'],[r'除负对数要翻转不等号。',r'所求是最小整数，应向上取整并检查临界前后次数。'])

put(13,1,[r'按外出后仅去题列三处且两次查找可靠的模型，图书馆、通宵教室、咖啡店的先验各0.9/3=0.3；不外出概率0.1。未在后两处找到，会排除这两条路径，却保留在家。']+bayes([R(3,10),R(3,10),R(3,10),R(1,10)],[R(1),R(0),R(0),R(1)],['图书馆','通宵教室','咖啡店','未外出'],'两处均未找到',[0])+[r'因此概率3/4，不是1。题设未保证他一定外出；若查找本身可能漏看，则还需查找检测率，原例采用已排除那两地点的理想观察。'],[r'不能漏掉0.1的未外出分支。',r'未找到被按确实不在处理，这是本题观察模型。'])
put(13,2,[r'第（1）无放回两次全白：(2/5)(1/4)=1/10。第一球白被拿走后只余1白、总4球。',r'第（2）第二球白分两路径：先白后白1/10，先黑后白(3/5)(2/4)=3/10，总4/10=2/5。也可按抽取位置对称性看第二球与第一球的白率相同。',r'第（3）已知第二白，求第一白：联合事件仍是全白，故(1/10)/(2/5)=1/4。条件分母是第二白的边际2/5，不是白白1/10，也不是第一次白后的1/4。'],[r'第二次白的无条件概率仍2/5，但在第一次白的条件下为1/4，二者不同。',r'最后一问是反向条件，用联合除以已知事件。'])
put(13,3,[r'按题意“其中一个是男孩”解释为至少一个男孩。三类性别组合BB、GG、混合的概率分别a、b、1−a−b，未假设双胞胎性别独立。',r'条件事件至少一男是GG的补，概率1−b；若另一个也男，则两个都男BB，概率a，且BB包含于条件事件。故P=a/(1−b)，要求b<1。',r'参数还应有a≥0、b≥0、a+b≤1，保证三类合法；由a≤1−b可见结果在[0,1]。若观察的是随机指定的一个孩子为男，条件会按男孩数量加权，不能擅用此至少一个模型。'],[r'双胞胎不能无条件假设为两个独立的各1/2性别。',r'“至少有一个男孩”与“随机指定的孩子是男孩”的抽样信息不同。'])
put(13,4,[r'总球数4n−1，无放回取n。条件“同色”分为全黑和全白两种互斥情形，有利子集数分别C(2n,n)与C(2n−1,n)，同一总分母在条件比中相消。',r'所以黑色条件概率为C(2n,n)/[C(2n,n)+C(2n−1,n)]。利用组合数阶乘，C(2n,n)/C(2n−1,n)=2n/(2n−n)=2。',r'于是所求2/(2+1)=2/3，对全部整数n≥1成立。n=1时抽一球自动同色，黑球占2/3，与公式核查一致。'],[r'已知同色后须重新归一化，不能仍答黑球原比例2n/(4n−1)。',r'全白与全黑子集数不同，不能因两种颜色而各赋1/2。'])
put(13,5,[r'分别以H₁为甲先、H₂为乙先，先验各1/2。E为全场第3次首次命中：前2枪未中、第3枪中。按各枪给定历史下命中率乘条件概率。',r'若甲先，顺序甲、乙、甲。首甲未中0.6，首乙未中0.5，第二次甲命中率0.45，所以P(E|H₁)=0.6×0.5×0.45=0.135。若乙先，顺序乙、甲、乙，P(E|H₂)=0.5×0.6×0.55=0.165。']+bayes([R(1,2),R(1,2)],[R(135,1000),R(165,1000)],['甲先','乙先'],'第3次才首次命中',[0]),[r'每人的命中率按自己的射击次数增加，不按全场枪数增加。',r'“第三次首次中”包含前两枪失败条件。'])
put(13,6,[r'A与C互斥给A包含于补C，进而AB也包含于补C。因此(AB)交补C仍为AB。',r'条件概率P(AB|补C)=P(AB交补C)/P(补C)=(1/3)/(1−1/4)=(1/3)/(3/4)=4/9。',r'P(补C)=3/4>0，条件分母合法。本题不需要P(A)、P(B)各自多少，也不能凭互斥就认为A、C独立。'],[r'互斥给AB不可能与C一起发生，所以条件分子仍是P(AB)。',r'不能把给出的1/3当作P(A)或P(B)。'])
put(13,7,[r'A−B表示A交补B。由A、B独立及补事件仍独立，P(A−B)=P(A)[1−P(B)]=P(A)×0.3=0.2，所以P(A)=2/3。',r'B−A表示补A交B，同样用独立性得P(B−A)=[1−P(A)]P(B)=(1/3)×0.7=7/30。',r'核查交P(AB)=(2/3)(0.7)=7/15；B边际0.7减此交也为7/30，A边际2/3减此交恰为0.2。'],[r'A−B与B−A方向相反，概率通常不同。',r'集合差概率不能用P(A)−P(B)，要减交。'])
put(13,8,[r'设c=P(C)。由A与B独立，P(AB)=1/2×1/2=1/4；由A与C独立，P(AC)=c/2。BC为空意味着AB与C也互斥。',r'因此P(AB∪C)=1/4+c，而AC包含于C，故条件分子P(AC交(AB∪C))=P(AC)=c/2。题给条件式成为(c/2)/(1/4+c)=1/4。',r'交叉相乘c/2=1/16+c/4，得c=1/4。此时分母1/2、分子1/8，比为1/4，且B、C互斥要求c≤1/2也满足。',r'只给A分别与B、C独立，不能声称三者相互独立；事实上B、C有正概率又互斥，不独立。'],[r'条件事件是整个AB∪C，分母不是P(B∪C)或P(ABC)。',r'两组独立不等于三者共同独立。'])
put(13,9,[r'令X、Y为甲、乙各n次的正面数。各人的抛掷均独立公平，所以P(X=k)=P(Y=k)=C(n,k)/2ⁿ，而且两人的次数统计也独立。',r'相等事件按共同次数k=0至n分成互斥情形(X=k,Y=k)。每项概率C(n,k)²/4ⁿ，求和得到题目第一表达式。',r'利用范德蒙德恒等式：从两组各n个元素的2n元素中选n个，按第一组选k个分类，共∑C(n,k)C(n,n−k)=C(2n,n)。因C(n,n−k)=C(n,k)，分子和为C(2n,n)，最终概率C(2n,n)/4ⁿ。',r'n=1时两人同面概率1/2，与C(2,1)/4相同；若n=0，两人次数都0、概率1，公式按C(0,0)=1也有效。'],[r'正面次数k不是等可能的n+1种值，要用二项概率。',r'平方来自甲乙各自概率相乘，不是把随机次数平方。'])
put(13,10,[r'三骰有两颗A、一颗B，无放回选2颗有C(3,2)=3种等可能对子。AA只有1种，AB有2种，所以类型权重1/3、2/3。类型确定后两骰独立掷出。',r'第（1）A红率2/6=1/3，B红率3/6=1/2，因此给AA全红率1/9，AB全红率1/6。']+bayes([R(1,3),R(2,3)],[R(1,9),R(1,6)],['AA','AB'],'两骰全红')+[r'第（2）同色为红红或白白，互斥。AA条件率(1/3)²+(2/3)²=5/9；AB条件率(1/3)(1/2)+(2/3)(1/2)=1/2。']+bayes([R(1,3),R(2,3)],[R(5,9),R(1,2)],['AA','AB'],'颜色相同'),[r'选中AA、AB的权重不是各1/2，因为AB有两种具体骰子对子。',r'同色包含全白，不能只算全红。'])
put(13,11,[r'取通常的Pólya罐模型：初始a、b为正球数，强化数c≥0；第k次后放回原球并加c个同色球。用对“任意初始a、b”的统一命题作数学归纳，而不是只固定一组库存。k=1时白球率a/(a+b)显然。',r'归纳假设：对于任意初始白、黑数，第k−1次取白的边际概率都等于该初始白比例。条件于第一次白或黑，剩余过程分别从(a+c,b)或(a,b+c)开始，故第k次白的条件概率分别(a+c)/(a+b+c)、a/(a+b+c)。',r'全概率给 $P(W_k)=\frac a{a+b}\frac{a+c}{a+b+c}+\frac b{a+b}\frac a{a+b+c}=\frac{a(a+b+c)}{(a+b)(a+b+c)}=\frac a{a+b}$，归纳完成。',r'强化会改变给定历史后的条件概率，但平均边际仍是初始比例。不能据边际相同就说各次独立；例如c>0时第一次白后下一次白概率(a+c)/(a+b+c)大于初始白率。'],[r'归纳命题需对任意初始库存成立，才能用于第一步后的两个新库存。',r'各次边际相同不意味着独立，强化恰会制造相关。'])

example('031-4832',[r'设A为第一袋取白、B为第二袋取白。题已给A发生，第一袋转入的是白球，故第二袋由原4白2黑变为5白2黑，共7球。',r'在这个已确定的库存条件下P(B|A)=5/7，无需再把第一袋取白概率2/5乘进最终条件答案。',r'用联合比核验：P(AB)=(2/5)(5/7)=2/7，再除P(A)=2/5仍为5/7。这区分了已知条件下的概率与联合发生概率。'],[r'转移球后第二袋总数变7，白数也增1。',r'已知A时不可把2/5再当最终答案的一部分。'])
example('032-5824',[r'令A为第一次次品、B为第二次正品。不放回共100件，次品10、正品90，P(A)=10/100。',r'已抽走一次品后，剩99件而正品仍90，所以P(B|A)=90/99。条件乘法给P(AB)=(10/100)(90/99)=1/11≈0.090909。',r'若用有序标签计数，有利10×90对，总100×99对，得到同一比值。题目指定先次后正，不能再乘2。'],[r'第一次拿走次品，正品数不减，但总数变99。',r'指定次序与一正一次不计顺序是不同事件。'])
example('033-5225',[r'第一袋移白或移黑两条路径互斥、穷尽。移白概率2/5，第二袋变5白2黑；移黑概率3/5，第二袋变4白3黑。两种总数都为7。']+bayes([R(2,5),R(3,5)],[R(5,7),R(4,7)],['从第一袋移白','从第一袋移黑'],'第二袋抽白')+[r'结果22/35介于4/7与5/7之间，符合对两个条件率作加权平均。此处没有给第一次颜色，所以必须两条一起算，不能直接沿用上一例5/7。'],[r'题目没有告诉第一球白，要计算两种可能转移。',r'第二袋白数4或5改变，而总数两种都7。'])
example('034-2830',[r'两个车间产量2∶3，来源先验分别2/5、3/5。合格率由各自次品率取补，为0.85、0.88。']+bayes([R(2,5),R(3,5)],[R(85,100),R(88,100)],['第一车间','第二车间'],'合格')+[r'也可算总次品率0.4×0.15+0.6×0.12=0.132，取补1−0.132=0.868，与全概率合格率一致。'],[r'按产量比加权，不能把两个车间条件率简单平均。',r'题目求合格，要先将次品率取补。'])
example('034-5426',[r'方案I、II互斥且穷尽，比例0.4、0.6。0.3%=0.003，0.1%=0.001，先把百分数换为正确的小数。']+bayes([R(2,5),R(3,5)],[R(3,1000),R(1,1000)],['方案I','方案II'],'次品')+[r'总次品率0.0018换回百分数为0.18%，在0.1%与0.3%之间。若将0.3%误读成0.3，结果会大100倍。'],[r'百分号是除100，0.3%不是30%。',r'方案占比与方案内部次品率属于不同层的概率。'])
example('034-7800',[r'先将汽车位置按初选门A与另两门分情况，三门先验等可能。初选A正确概率1/3，初选A错误概率2/3。主持人知道位置、始终打开未选的羊门，这一行为不是随意开门。',r'若初选正确，剩下两门都是羊，主持人开一门后换到另一门必输；若初选错误，另两门是一车一羊，主持人被规则迫使开羊，留下的唯一未选未开门必是车，换门必赢。',r'所以换门胜率=P(初选错误)=2/3，不换胜率=P(初选正确)=1/3，换门更优。开一扇羊门并不会把最初三分之一自动平均成二分之一，因为主持人行为依汽车位置选择。',r'本结论按题目明确的标准主持规则；若主持人不知道汽车位置、可能开出车，或只在特定位置才提供换门，观察与策略模型都变了，不能照搬2/3。'],[r'主持人有信息且按规则开羊，两个未开门不因数量为2就各1/2。',r'策略比较围绕最初是否选对，不需要假定主持人在两羊门间如何偏好。'])
example('035-8483',[r'方案1和2在各自患者中小、大结石两组占比不同，所以总治愈率应各按自己的构成权重计算，不能把两个亚组率各取一半。',r'方案1总率=0.23×0.93+0.77×0.73=0.2139+0.5621=0.776。方案2总率=0.67×0.87+0.33×0.69=0.5829+0.2277=0.8106。',r'分层比较时方案1在小结石93%>87%、大结石73%>69%，均高；但其病例77%是治愈率较低的大结石，而方案2只有33%，不同组别构成使总体比较反向，这就是本例的辛普森悖论。',r'总体加权率与同类患者内的条件率回答不同问题。仅凭两套未统一病例构成的总体率，不能把差异直接归因为方案本身的效果；此处解释的是给定统计表的混合权重。'],[r'总率必须按各方案自己的病例构成加权。',r'分层均高不保证不同混合权重下总体也高，不能忽略组别比例。'])
example('037-4085',[r'设H为带菌、E为阳性。发病率0.5%换为0.005；健康者先验0.995。检测灵敏度0.95是P(E|H)，误报率0.01是P(E|补H)，不是反向后验。']+bayes([R(5,1000),R(995,1000)],[R(95,100),R(1,100)],['带菌','健康'],'检测阳性',[0])+[r'假设20000人的同模型总体，可预期100带菌中95阳性，19900健康中199阳性；阳性合计294，其中真正带菌95，后验95/294≈0.323129。这是题设概率模型的计算，不把95%的灵敏度误当后验。'],[r'必须计入人数基数很大的健康人误报路径。',r'P(阳性|带菌)与P(带菌|阳性)不是同一概率。'])
example('038-4769',[r'6球中4新2旧，练习取2球无放回。令K为练习取到新球数0、1、2，有利数C(4,k)C(2,2−k)分别1、8、6，全部C(6,2)=15，因此先验1/15、8/15、6/15。',r'练习后球放回，但用过的新球变旧。条件于K=k，比赛前仍有4−k新球、总数6；比赛取两新概率C(4−k,2)/15，依次6/15、3/15、1/15。']+bayes([R(1,15),R(8,15),R(6,15)],[R(6,15),R(3,15),R(1,15)],['练习0新','练习1新','练习2新'],'比赛取到2新',[0,1,2])+[r'总比赛双新率4/25，后验1/6、4/6、1/6，最大为练习1新。后验既受各情形先验多少影响，也受它们产生观察的可能性影响，不能只比较剩新球最多的K=0。'],[r'放回恢复总球数，不会让已经用过的新球重新变新。',r'最可能来源应比较先验乘似然后的归一化结果，不只看单个条件概率。'])
example('040-2204',[r'每次有放回且均匀抽，袋内始终4白2黑，所以P(A)=P(B)=4/6=2/3。A发生后仍是原库存，P(B|A)=2/3；A不发生后放回黑球，P(B|补A)=2/3。',r'联合P(AB)=P(A)P(B|A)=(2/3)²=4/9，恰等于P(A)P(B)，因此A、B独立。两个条件概率也都等于B的边际率，符合等价定义。',r'这里独立来自抽后放回并重新随机选球的机制；若不放回，P(B|A)=3/5就不同于2/3，不能沿用当前结论。'],[r'有放回使库存恢复，第二次白率不随第一次颜色改变。',r'不要把不放回的3/5代进本例。'])
example('041-2242',[r'将四张牌区分为红牌、白牌、黄牌、三色牌，各概率1/4。含红的A由红牌和三色牌组成，B、C同理，每个概率1/2。',r'任意两种颜色同时出现只能抽三色牌，故P(AB)=P(AC)=P(BC)=1/4=(1/2)(1/2)，三对分别独立。',r'三色同时出现也只在三色牌，P(ABC)=1/4，而三边际乘积1/8，二者不等，故不相互独立。相互独立要求所有非空子组的交概率乘积关系，不能只检查三对。'],[r'两两独立不推出相互独立。',r'三重交与每个两重交恰是同一张三色牌，概率都是1/4。'])
example('041-4745',[r'事件Aᵢ为第i车床不需维护，概率0.9、0.8、0.85。至少一台不需维护的对立是三台都需维护，注意不是三台都不需维护。',r'需维护概率分别0.1、0.2、0.15；题设独立使全需维护概率0.1×0.2×0.15=0.003。',r'所以至少一台无需维护概率1−0.003=0.997。直接将0.9+0.8+0.85相加会超过1，因多个车床同时无需维护的情形重叠。'],[r'“至少一台不需”取补后是“所有都需”，两个量词要一起翻转。',r'题给的是不需维护率，不可再把0.9当故障率。'])
example('042-1808',[r'串联装置必须所有n元件均正常才正常，独立且每个正常率p给P(I正常)=pⁿ。',r'并联装置只要一个正常即可，对立是全部故障，每个故障率1−p，因此P(II正常)=1−(1−p)ⁿ。',r'可用事件包含比较：全正常包含于至少一个正常，故并联可靠性不小于串联。0<p<1且n≥2时，恰有一部分正常有正概率，包含严格，所以并联更高。n=1二者同为p；p=0或1时结果也相等。'],[r'串联对全部正常求交，并联对全部失败求补，不能交换。',r'严格大于需0<p<1、n≥2，边界可相等。'])
example('042-7354',[r'公司发生至少一次赔付的事件是n人中至少一人出意外，补事件全部没有意外。各人独立且无意外率0.99，P(赔付)=1−0.99ⁿ。',r'要求超过1/2（严格），即0.99ⁿ<1/2。取对数并除以负数ln0.99，得到n>ln(1/2)/ln0.99≈'+format(math.log(.5)/math.log(.99),'.8f')+'，故最小整数69。',r'检验68人赔付率≈'+format(1-.99**68,'.8f')+'<1/2，69人≈'+format(1-.99**69,'.8f')+'>1/2，且随人数单调增加，确认最少69。题问是否发生赔付，不是赔付金额期望。'],[r'“超过”与“至少达到”的不等号不同，取整前须确认边界。',r'不能用0.01n直接当至少一次的准确概率。'])
example('044-2466',[r'5次独立有放回，次品率0.2，所以次品数X∼B(5,0.2)。指定3次为次品、其余2次正品的概率0.2³0.8²，3次位置有C(5,3)=10种。',r'故P(X=3)=10×0.008×0.64=0.0512。至多3次是X=0、1、2、3，更方便取对立X=4或5。',r'P(X≤3)=1−C(5,4)0.2⁴0.8−0.2⁵=1−0.0064−0.00032=0.99328。两补事件互斥，且与X≤3穷尽全部0至5结果。'],[r'至多3包含0至3，不是只算恰3。',r'补事件是4或5，不能只减5次全次品。'])
example('044-4430',[r'全部仪器先分无需调试0.8与需调试0.2。前者必合格，后者条件合格率0.7，因此总合格率0.8×1+0.2×0.7=0.94；总次品率0.2×0.3=0.06。',r'按题设独立生产及随机抽取的大批量模型，三台的次品状态同率独立。恰一台次品有C(3,1)=3种位置，每种0.06×0.94²。',r'所以概率3×0.06×0.8836=0.159048。不能把需调试20%全部视作次品；其中70%调试后合格。若是已知固定有限库存中不放回抽样，则应按库存数用超几何，原例采用独立大批量模型。'],[r'需调试不是最终次品，须乘调试后仍失败的30%。',r'恰1次品包含三种位置，且其余两台应按总体合格率0.94。'])
example('045-8000',[r'设p=P(A)，则不畅销概率1−p。题给可能性比2∶1，意思p=2(1−p)，而不是p比不畅销多2个百分点。',r'解得3p=2，所以p=2/3、不畅销1/3；两者和1，且比值恰2，核验条件。',r'这是基于经理给定主观判断的概率赋值，题目未提供销售频数，不能把它说成由大样本估计出的客观频率。数学约束是两个互补概率和1。'],[r'概率比2∶1要归一化为2/3、1/3，不能把畅销直接写2。',r'“两倍”是乘法比例，不是相差固定百分点。'])

if __name__=='__main__':author.main()
